  `fecha_primer_pago` date DEFAULT NULL,
  `ciclo` int NOT NULL,
  `ciclo_inicio_mora` int DEFAULT NULL,
  `abono_recuperacion` decimal(12,2) DEFAULT NULL,
  `comision_apertura` decimal(12,2) NOT NULL DEFAULT '100.00',
  `tasa_asignada` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ej. TCIN21, TCGN10',
  `monto_otorgado` decimal(10,2) NOT NULL,
  `interes` decimal(10,2) NOT NULL,
  `porcentaje_interes` decimal(5,2) DEFAULT NULL COMMENT 'Porcentaje de interes aplicado ej. 21.00',
  `total` decimal(10,2) NOT NULL,
  `saldo_pendiente` decimal(12,2) DEFAULT NULL,
  `credito_padre_id` bigint unsigned DEFAULT NULL,
  `plazos` int NOT NULL,
  `valor_ficha` decimal(10,2) NOT NULL,
  `dias_pago` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tabla_amortizacion` json DEFAULT NULL,
  `estado` enum('Activo','Finalizado','Cancelado','EnMora','CerradoSinRenovacion') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Activo',
  `es_personalizado` tinyint(1) NOT NULL DEFAULT '0',
  `es_adicional` tinyint(1) NOT NULL DEFAULT '0',
  `dias_mora_cache` int NOT NULL DEFAULT '0',
  `ubicacion_expediente` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notas_expediente` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`num_prog`),
  KEY `creditos_id_cliente_foreign` (`id_cliente`),
  KEY `creditos_id_asesor_foreign` (`id_asesor`),
  KEY `creditos_id_grupo_foreign` (`id_grupo`),
  KEY `creditos_credito_padre_id_foreign` (`credito_padre_id`),
  CONSTRAINT `creditos_credito_padre_id_foreign` FOREIGN KEY (`credito_padre_id`) REFERENCES `creditos` (`num_prog`) ON DELETE SET NULL,
  CONSTRAINT `creditos_id_asesor_foreign` FOREIGN KEY (`id_asesor`) REFERENCES `asesores` (`id`) ON DELETE CASCADE,
  CONSTRAINT `creditos_id_cliente_foreign` FOREIGN KEY (`id_cliente`) REFERENCES `clientes` (`id_cliente`) ON DELETE CASCADE,
  CONSTRAINT `creditos_id_grupo_foreign` FOREIGN KEY (`id_grupo`) REFERENCES `grupos` (`id`) ON DELETE CASCADE
